-- Read-only source for the next independently reviewed recovery posting.
-- Actual returned money must already be posted;never book cash a second time.
CREATE FUNCTION public.provider_dispute_loss_recovery_source(p_loss uuid,p_on date) RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path=pg_catalog SET DateStyle='ISO,YMD' AS $$
DECLARE l record;c record;a record;e record;principal record;original jsonb;s jsonb;k jsonb;asset jsonb;debits numeric;returns numeric;factor numeric;amount numeric;proof jsonb;BEGIN
 SELECT * INTO l FROM public.provider_dispute_losses WHERE id=p_loss;IF l.id IS NULL THEN RETURN NULL;END IF;
 SELECT pc.*,cl.time_zone INTO c FROM public.provider_collections pc JOIN public.classes cl ON cl.academy_id=pc.academy_id AND cl.id=pc.class_id WHERE pc.academy_id=l.academy_id AND pc.id=l.collection_id;
 IF c.id IS NULL OR p_on IS NULL OR p_on<l.posted_on OR p_on>(statement_timestamp() AT TIME ZONE c.time_zone)::date THEN RETURN NULL;END IF;
 SELECT * INTO principal FROM public.checkout_provider_inspections WHERE academy_id=c.academy_id AND start_id=c.start_id ORDER BY received_at DESC,id DESC LIMIT 1;SELECT inspection INTO original FROM public.checkout_provider_inspections WHERE academy_id=c.academy_id AND id=c.inspection_id;
 IF principal.id IS NULL OR principal.object_conflict OR principal.inspection-ARRAY['state','disputed','paymentVerified','refundedAmount'] IS DISTINCT FROM original-ARRAY['state','disputed','paymentVerified','refundedAmount'] OR principal.inspection->>'state' NOT IN('captured','requires_review') THEN RETURN NULL;END IF;
 s=public.provider_dispute_resolution_source(c.id,p_on);IF s IS NULL OR s ? 'unavailable' OR s->'onIsFuture' IS DISTINCT FROM 'false'::jsonb OR s->'pageChainComplete' IS DISTINCT FROM 'true'::jsonb OR s->'pageChainConflict' IS DISTINCT FROM 'false'::jsonb OR s->'disputeAttentionRetained' IS DISTINCT FROM 'true'::jsonb THEN RETURN NULL;END IF;
 SELECT value INTO k FROM jsonb_array_elements(s->'cases') WHERE value->>'disputeId'=l.dispute_id;
 IF k IS NULL OR k->>'status' IS NULL OR k->>'status' NOT IN('lost','won','warning_closed','prevented') OR k->'ownershipConflict' IS DISTINCT FROM 'false'::jsonb OR k->'requiresFxReview' IS DISTINCT FROM 'false'::jsonb OR k->'exceedsOriginalAmount' IS DISTINCT FROM 'false'::jsonb OR k->>'providerUnitScale' IS NULL THEN RETURN NULL;END IF;
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(s->'movements') m WHERE m->>'disputeId'=l.dispute_id) OR EXISTS(SELECT 1 FROM jsonb_array_elements(s->'movements') m WHERE m->>'disputeId'=l.dispute_id AND(m->'observed' IS DISTINCT FROM 'true'::jsonb OR m->'recognized' IS DISTINCT FROM 'true'::jsonb OR m->'ownershipConflict' IS DISTINCT FROM 'false'::jsonb OR m->'requiresFxReview' IS DISTINCT FROM 'false'::jsonb OR(m->'amountMatched' IS DISTINCT FROM 'true'::jsonb AND NOT((m->>'grossMinor')::numeric>0 AND(m->>'grossMinor')::numeric<(k->>'amountMinor')::numeric)) OR m->'accountingMatchesLatest' IS DISTINCT FROM 'true'::jsonb OR m->'futureDatedAccounting' IS DISTINCT FROM 'false'::jsonb OR m->>'postingId' IS NULL OR m->'currencyCode' IS DISTINCT FROM k->'currencyCode' OR m->'providerUnitScale' IS DISTINCT FROM k->'providerUnitScale' OR m->>'disputedAccountId' IS DISTINCT FROM l.disputed_account::text OR m->'accountingCurrencyId' IS DISTINCT FROM l.source->'currencyId' OR m->'accountingUnitScale' IS DISTINCT FROM l.source->'unitScale')) THEN RETURN NULL;END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(s->'movements') m JOIN public.checkout_dispute_balance_inspections i ON i.academy_id=c.academy_id AND i.id=(m->>'inspectionId')::uuid WHERE m->>'disputeId'=l.dispute_id AND(m->>'grossMinor')::numeric>0 AND i.balance_inspection->>'status' IS DISTINCT FROM 'available') THEN RETURN NULL;END IF;
 SELECT * INTO a FROM public.finance_account_catalogue WHERE academy_id=c.academy_id AND id=l.disputed_account;SELECT * INTO e FROM public.finance_account_catalogue WHERE academy_id=c.academy_id AND id=l.expense_account;
 IF a.id IS NULL OR e.id IS NULL OR a.id=e.id OR NOT a.active OR NOT e.active OR a.kind<>'asset' OR a.normal_balance<>'debit' OR a.operational_role<>'other' OR e.kind<>'expense' OR e.operational_role<>'expense' OR a.currency_id<>e.currency_id OR a.unit_scale<>e.unit_scale OR a.currency_id::text IS DISTINCT FROM l.source->>'currencyId' OR a.currency_code IS DISTINCT FROM k->>'currencyCode' OR a.unit_scale IS DISTINCT FROM(l.source->>'unitScale')::integer OR(a.hub_id IS NOT NULL AND a.hub_id<>c.hub_id) OR(e.hub_id IS NOT NULL AND e.hub_id<>c.hub_id) THEN RETURN NULL;END IF;
 IF(SELECT count(*) FROM jsonb_array_elements(s->'disputedAssets') x WHERE x->>'disputeId'=l.dispute_id AND(x->>'balanceMinor')::numeric<>0)<>1 THEN RETURN NULL;END IF;
 SELECT value INTO asset FROM jsonb_array_elements(s->'disputedAssets') WHERE value->>'disputeId'=l.dispute_id AND value->>'accountId'=a.id::text AND value->>'currencyId'=a.currency_id::text AND(value->>'unitScale')::integer=a.unit_scale;
 amount=-(asset->>'balanceMinor')::numeric;factor=power(10::numeric,a.unit_scale)/power(10::numeric,(k->>'providerUnitScale')::integer);
 SELECT coalesce(sum(-(m->>'grossMinor')::numeric) FILTER(WHERE(m->>'grossMinor')::numeric<0),0),coalesce(sum((m->>'grossMinor')::numeric) FILTER(WHERE(m->>'grossMinor')::numeric>0),0) INTO debits,returns FROM jsonb_array_elements(s->'movements') m WHERE m->>'disputeId'=l.dispute_id;
 IF amount IS NULL OR amount<=0 OR amount>l.amount_minor OR amount>=1e38 OR amount<>trunc(amount) OR debits<>(k->>'amountMinor')::numeric OR returns<=0 OR returns>debits OR l.amount_minor-amount<>(debits-returns)*factor OR(k->>'status'<>'lost' AND returns<>debits) THEN RETURN NULL;END IF;
 proof=jsonb_build_object('version',1,'lossId',l.id,'sourceFingerprint',s->'sourceFingerprint','postedOn',p_on::text,'disputedVersion',a.version,'expenseVersion',e.version,'amountMinor',trunc(amount)::text);
 RETURN jsonb_build_object('lossId',l.id,'collectionId',c.id,'disputeId',l.dispute_id,'sourceStamp',encode(sha256(convert_to(proof::text,'UTF8')),'hex'),'postedOn',p_on::text,'disputedAccountId',a.id,'disputedVersion',a.version,'expenseAccountId',e.id,'expenseVersion',e.version,'currencyId',a.currency_id,'currencyCode',a.currency_code,'unitScale',a.unit_scale,'amountMinor',trunc(amount)::text,'originalLossMinor',trunc(l.amount_minor)::text,'remainingLossMinor',trunc(l.amount_minor-amount)::text,'lines',jsonb_build_array(jsonb_build_object('accountId',a.id,'accountVersion',a.version,'side','debit','amountMinor',trunc(amount)::text),jsonb_build_object('accountId',e.id,'accountVersion',e.version,'side','credit','amountMinor',trunc(amount)::text)));
END $$;
REVOKE ALL ON FUNCTION public.provider_dispute_loss_recovery_source(uuid,date) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.provider_dispute_loss_recovery_source(uuid,date) TO kavosh_runtime;
CREATE OR REPLACE FUNCTION public.schema_revision() RETURNS integer LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$ SELECT 337 $$;
